CREATE TEMP TABLE vitale_release_patch AS
SELECT * FROM jsonb_to_recordset($vitale_patch$[{"slug": "bicicleta-eletrica-no-dia-a-dia-quando-ela-pode-valer-a-pena", "expected_revision": 5, "old_type": "test", "new_type": "economy", "old_title": "Bicicleta elétrica no dia a dia: quando ela pode valer a pena?", "new_title": "Bicicleta elétrica no dia a dia: quando ela pode valer a pena?", "blocks": {"4": {"before": "A energia elétrica é apenas uma parte do custo. A fonte estima um gasto de **1 a 2 centavos de energia por quilômetro** e dá como exemplo 20 centavos para um trecho de 10 km. Esses valores servem para ilustrar a conta, não para prever a despesa de toda bicicleta: o consumo e a tarifa podem variar.\n\nHá ainda o preço de compra e a futura substituição da bateria.000 mencionada para baterias é uma referência ampla, não um orçamento para um modelo específico. Manutenção também entra na conta. Comparar apenas o gasto de eletricidade com uma passagem de ônibus ou um tanque de combustível deixaria esses custos de fora.\n\nO valor que cabe no orçamento importa mais do que partir de um preço apresentado como ideal.000, mas isso não confirma a qualidade nem o preço atual de uma oferta. **Não vale comprometer o orçamento contando com uma economia que ainda não foi calculada para a sua rotina.**", "after": "A energia elétrica é apenas uma parte do custo. A fonte estima um gasto de **1 a 2 centavos de energia por quilômetro** e dá como exemplo 20 centavos para um trecho de 10 km. Esses valores servem para ilustrar a conta, não para prever a despesa de toda bicicleta: o consumo e a tarifa podem variar.\n\nHá ainda o preço de compra e a futura substituição da bateria. A faixa de R$ 800 a R$ 2.000 mencionada para baterias é uma referência ampla, não um orçamento para um modelo específico. Manutenção também entra na conta. Comparar apenas o gasto de eletricidade com uma passagem de ônibus ou um tanque de combustível deixaria esses custos de fora.\n\nO valor que cabe no orçamento importa mais do que partir de um preço apresentado como ideal. A fonte cita opções a partir de R$ 3.000, mas isso não confirma a qualidade nem o preço atual de uma oferta. **Não vale comprometer o orçamento contando com uma economia que ainda não foi calculada para a sua rotina.**"}}, "faq": {}}, {"slug": "bicicleta-eletrica-o-que-saber-sobre-bateria-recarga-e-manutencao-antes-de-comprar", "expected_revision": 4, "old_type": "test", "new_type": "tips", "old_title": "Bicicleta elétrica: o que saber sobre bateria, recarga e manutenção antes de comprar", "new_title": "Bicicleta elétrica: o que saber sobre bateria, recarga e manutenção antes de comprar", "blocks": {}, "faq": {}}, {"slug": "bicicleta-eletrica-ou-scooter-eletrica-o-que-muda-no-uso-diario", "expected_revision": 4, "old_type": "test", "new_type": "comparison", "old_title": "Bicicleta elétrica ou scooter elétrica: o que muda no uso diário?", "new_title": "Bicicleta elétrica ou scooter elétrica: o que muda no uso diário?", "blocks": {}, "faq": {}}, {"slug": "bicicleta-eletrica-para-duas-pessoas-v8-pro-v40-pro-ou-v9-max", "expected_revision": 4, "old_type": "test", "new_type": "comparison", "old_title": "Bicicleta elétrica para duas pessoas: V8 Pro, V40 Pro ou V9 Max?", "new_title": "Bicicleta elétrica para duas pessoas: V8 Pro, V40 Pro ou V9 Max?", "blocks": {}, "faq": {}}, {"slug": "bicicleta-eletrica-para-terra-batida-como-escolher-entre-quatro-modelos", "expected_revision": 7, "old_type": "test", "new_type": "comparison", "old_title": "Bicicleta elétrica para terra batida: como escolher entre quatro modelos", "new_title": "Bicicleta elétrica para terra batida: como escolher entre quatro modelos", "blocks": {}, "faq": {}}, {"slug": "bicicleta-eletrica-pode-reduzir-seus-gastos-de-transporte-o-que-comparar-antes-de-decidir", "expected_revision": 4, "old_type": "test", "new_type": "economy", "old_title": "Bicicleta elétrica pode reduzir seus gastos de transporte? O que comparar antes de decidir", "new_title": "Bicicleta elétrica pode reduzir seus gastos de transporte? O que comparar antes de decidir", "blocks": {"1": {"before": "000 por mês para ter um carro.000**. A conta anual representa o gasto informado por aquela pessoa, não uma economia demonstrada.\n\nSe o carro continuar na garagem, parte dos custos de mantê-lo pode permanecer. Se a bike substituir apenas algumas viagens, a comparação precisa considerar os gastos associados a essas viagens e também o custo de adquirir e usar a bicicleta.000 por mês: a quantia que pode deixar de gastar muda conforme o veículo que mantém e a frequência com que consegue fazer a troca.\n\nHá ainda uma distinção entre caber no orçamento de compra e custar menos ao longo do tempo. Um preço anunciado pode ajudar a decidir se a compra é viável hoje, mas, sozinho, não prova quanto ela economizará nos meses seguintes.", "after": "O exemplo da fonte é de uma pessoa que informa gastar **R$ 5.000 por mês para ter um carro**, equivalentes a **R$ 60.000 em 12 meses**. A conta anual representa o gasto informado por aquela pessoa, não uma economia demonstrada.\n\nSe o carro continuar na garagem, parte dos custos de mantê-lo pode permanecer. Se a bike substituir apenas algumas viagens, a comparação precisa considerar os gastos associados a essas viagens e também o custo de adquirir e usar a bicicleta. Isso não significa economizar R$ 5.000 por mês: a quantia que pode deixar de gastar muda conforme o veículo que mantém e a frequência com que consegue fazer a troca.\n\nHá ainda uma distinção entre caber no orçamento de compra e custar menos ao longo do tempo. Um preço anunciado pode ajudar a decidir se a compra é viável hoje, mas, sozinho, não prova quanto ela economizará nos meses seguintes."}}, "faq": {"1": {"before": "Não necessariamente.000 é a multiplicação daquele gasto mensal informado por 12. A economia dependeria dos custos que deixariam de existir; se o carro for mantido, parte deles pode continuar.", "after": "Não necessariamente. R$ 60.000 é a multiplicação daquele gasto mensal informado por 12. A economia dependeria dos custos que deixariam de existir; se o carro for mantido, parte deles pode continuar."}}}, {"slug": "cinco-bikes-eletricas-para-delivery-como-escolher-pela-bateria-e-pela-carga", "expected_revision": 4, "old_type": "test", "new_type": "comparison", "old_title": "Cinco bikes elétricas para delivery: como escolher pela bateria e pela carga", "new_title": "Cinco bikes elétricas para delivery: como escolher pela bateria e pela carga", "blocks": {}, "faq": {}}, {"slug": "como-escolher-a-proxima-bicicleta-eletrica-sem-olhar-so-para-a-potencia", "expected_revision": 4, "old_type": "test", "new_type": "guide", "old_title": "Como escolher a próxima bicicleta elétrica sem olhar só para a potência", "new_title": "Como escolher a próxima bicicleta elétrica sem olhar só para a potência", "blocks": {}, "faq": {}}, {"slug": "como-escolher-uma-bicicleta-eletrica-que-cabe-no-seu-uso-e-no-seu-bolso", "expected_revision": 3, "old_type": "test", "new_type": "guide", "old_title": "Como escolher uma bicicleta elétrica que cabe no seu uso e no seu bolso", "new_title": "Como escolher uma bicicleta elétrica que cabe no seu uso e no seu bolso", "blocks": {}, "faq": {}}, {"slug": "como-gravar-videos-andando-de-bike-ou-moto-com-o-celular", "expected_revision": 4, "old_type": "test", "new_type": "tips", "old_title": "Como gravar vídeos andando de bike ou moto com o celular", "new_title": "Como gravar vídeos andando de bike ou moto com o celular", "blocks": {}, "faq": {}}, {"slug": "como-trancar-a-bicicleta-eletrica-e-reduzir-o-risco-de-furto", "expected_revision": 3, "old_type": "test", "new_type": "tips", "old_title": "Como trancar a bicicleta elétrica e reduzir o risco de furto", "new_title": "Como trancar a bicicleta elétrica e reduzir o risco de furto", "blocks": {}, "faq": {}}, {"slug": "ft03-v35-ou-v9-max-qual-bicicleta-eletrica-combina-com-seu-uso", "expected_revision": 4, "old_type": "test", "new_type": "comparison", "old_title": "FT03, V35 ou V9 Max: qual bicicleta elétrica combina com seu uso?", "new_title": "FT03, V35 ou V9 Max: qual bicicleta elétrica combina com seu uso?", "blocks": {}, "faq": {}}, {"slug": "ft03-v9-max-ou-ouxi-gt20-qual-bicicleta-eletrica-combina-com-seu-uso", "expected_revision": 4, "old_type": "test", "new_type": "comparison", "old_title": "FT03, V9 Max ou Ouxi GT20: qual bicicleta elétrica combina com seu uso?", "new_title": "FT03, V9 Max ou Ouxi GT20: qual bicicleta elétrica combina com seu uso?", "blocks": {}, "faq": {}}, {"slug": "inow-v20-pro-ou-ouxi-v8-ultra-o-que-muda-na-escolha", "expected_revision": 4, "old_type": "comparison", "new_type": "comparison", "old_title": "Inow V20 Pro ou OUXI V8 Ultra: o que muda na escolha?", "new_title": "Inow V20 Pro ou OUXI V8 Ultra: o que muda na escolha?", "blocks": {"0": {"before": "O banco bipartido é o ponto em comum mais útil das duas bicicletas. A parte traseira pode ser removida ou adaptada, conforme a necessidade de levar um passageiro, instalar um baú ou usar a região para outros acessórios. Isso interessa especialmente a quem alterna deslocamentos pessoais com tarefas de trabalho ou da família.\n\n468**. Esses eram preços de ofertas citadas naquele momento, não valores atuais garantidos; as condições de pagamento também eram diferentes. Se a distância de preço continuar relevante quando você for comprar, a pergunta é se a resposta do motor e os equipamentos da V8 Ultra justificam a diferença para o seu uso. Se não justificarem, as duas já oferecem a principal vantagem prática dessa proposta: a traseira adaptável.", "after": "O banco bipartido é o ponto em comum mais útil das duas bicicletas. A parte traseira pode ser removida ou adaptada, conforme a necessidade de levar um passageiro, instalar um baú ou usar a região para outros acessórios. Isso interessa especialmente a quem alterna deslocamentos pessoais com tarefas de trabalho ou da família.\n\nA fonte citou, em setembro de 2026, **R$ 5.916 no Pix para a V20 Pro e R$ 7.468 no total, em dez parcelas, para a V8 Ultra**. Esses eram preços de ofertas citadas naquele momento, não valores atuais garantidos; as condições de pagamento também eram diferentes. Se a distância de preço continuar relevante quando você for comprar, a pergunta é se a resposta do motor e os equipamentos da V8 Ultra justificam a diferença para o seu uso. Se não justificarem, as duas já oferecem a principal vantagem prática dessa proposta: a traseira adaptável."}}, "faq": {}}, {"slug": "inow-v35-o-que-as-duas-baterias-mudam-no-uso-diario-82ab63bdd783", "expected_revision": 4, "old_type": "test", "new_type": "test", "old_title": "Inow V35: o que as duas baterias mudam no uso diário", "new_title": "Inow V35: autonomia, recarga e comandos no uso diário", "blocks": {}, "faq": {}}, {"slug": "mangosteen-ft03-ou-wanshida-gt2000-o-que-muda-alem-do-preco", "expected_revision": 4, "old_type": "test", "new_type": "comparison", "old_title": "Mangosteen FT03 ou WANSHIDA GT2000: o que muda além do preço?", "new_title": "Mangosteen FT03 ou WANSHIDA GT2000: o que muda além do preço?", "blocks": {"0": {"before": "949 em dez parcelas**.790 em dez parcelas**. São preços de uma oferta específica, sujeitos a mudança; não servem como cotação atual nem garantem que outra unidade terá as mesmas condições.\n\n841. Antes de decidir se vale pagá-la, confira o preço vigente, o valor total das parcelas, o vendedor e a configuração da unidade anunciada. Depois, compare o que esse dinheiro adicional traz para o seu uso: principalmente bateria e equipamentos.", "after": "A oferta citada para a **FT03 era de R$ 5.802 no Pix ou R$ 5.949 no total, em dez parcelas**; para a **GT2000, R$ 9.790 no total, em dez parcelas**. São preços de uma oferta específica, sujeitos a mudança; não servem como cotação atual nem garantem que outra unidade terá as mesmas condições.\n\nNo parcelamento citado, a diferença entre os totais era de R$ 3.841. Antes de decidir se vale pagá-la, confira o preço vigente, o valor total das parcelas, o vendedor e a configuração da unidade anunciada. Depois, compare o que esse dinheiro adicional traz para o seu uso: principalmente bateria e equipamentos."}}, "faq": {"0": {"before": "790 em dez parcelas. Confirme os valores atuais antes de comparar ou comprar.", "after": "Nas ofertas citadas, a FT03 custava R$ 5.802 no Pix ou R$ 5.949 no total, em dez parcelas, e a GT2000, R$ 9.790 no total, em dez parcelas. Confirme os valores atuais antes de comparar ou comprar."}}}, {"slug": "moto-eletrica-vale-a-pena-o-que-avaliar-antes-de-comprar", "expected_revision": 4, "old_type": "test", "new_type": "guide", "old_title": "Moto elétrica vale a pena? O que avaliar antes de comprar", "new_title": "Moto elétrica vale a pena? O que avaliar antes de comprar", "blocks": {}, "faq": {}}, {"slug": "ouxi-gt20-pro-ou-wanshida-gt2000-qual-faz-mais-sentido-para-voce", "expected_revision": 4, "old_type": "test", "new_type": "comparison", "old_title": "Ouxi GT20 Pro ou WANSHIDA GT2000: qual faz mais sentido para você?", "new_title": "Ouxi GT20 Pro ou WANSHIDA GT2000: qual faz mais sentido para você?", "blocks": {"6": {"before": "As duas são descritas com setas dianteiras e traseiras, indicação das setas no painel, NFC para ligar e desligar e alarme. Há, porém, uma ressalva prática sobre o painel: a visibilidade pode piorar sob sol forte. Se você depende dessas informações durante o uso, vale conferir o painel pessoalmente quando possível.\n\nAlguns detalhes foram apresentados como prováveis, não como configuração confirmada de todas as unidades — entre eles, o tipo de painel da GT20 Pro e o acelerador de cada modelo. Por isso, **não decida apenas pelo nome do modelo**: peça ao vendedor fotos e a especificação da unidade anunciada, sobretudo se um comando ou acessório for importante para você.\n\n500 em ofertas parceladas. Eles não são preços atuais garantidos. Compare o valor efetivo, as condições de pagamento e o suporte oferecido por cada vendedor antes de concluir qual custa menos para você.", "after": "As duas são descritas com setas dianteiras e traseiras, indicação das setas no painel, NFC para ligar e desligar e alarme. Há, porém, uma ressalva prática sobre o painel: a visibilidade pode piorar sob sol forte. Se você depende dessas informações durante o uso, vale conferir o painel pessoalmente quando possível.\n\nAlguns detalhes foram apresentados como prováveis, não como configuração confirmada de todas as unidades — entre eles, o tipo de painel da GT20 Pro e o acelerador de cada modelo. Por isso, **não decida apenas pelo nome do modelo**: peça ao vendedor fotos e a especificação da unidade anunciada, sobretudo se um comando ou acessório for importante para você.\n\nOs valores citados eram aproximadamente R$ 7.100 para a GT20 Pro e R$ 10.500 para a GT2000, em ofertas parceladas. Eles não são preços atuais garantidos. Compare o valor efetivo, as condições de pagamento e o suporte oferecido por cada vendedor antes de concluir qual custa menos para você."}}, "faq": {}}, {"slug": "v29-pro-wanshida-v8-pro-s-ou-inow-v35-qual-faz-mais-sentido-para-voce", "expected_revision": 4, "old_type": "test", "new_type": "comparison", "old_title": "V29 Pro, WANSHIDA V8 Pro S ou Inow V35: qual faz mais sentido para você?", "new_title": "V29 Pro, WANSHIDA V8 Pro S ou Inow V35: qual faz mais sentido para você?", "blocks": {}, "faq": {}}, {"slug": "v9-max-20ah-o-que-muda-com-a-bateria-maior-e-o-que-conferir-antes-de-comprar", "expected_revision": 4, "old_type": "test", "new_type": "test", "old_title": "V9 Max 20ah: o que muda com a bateria maior e o que conferir antes de comprar", "new_title": "V9 Max 20ah: o que muda com a bateria maior e o que conferir antes de comprar", "blocks": {"6": {"before": "**Esses valores não são preço atual garantido.776; por isso, compare o custo total, e não apenas o valor mensal.\n\nO ponto de partida para decidir é verificar se a oferta atual corresponde à V9 Max 20ah com bateria removível de 48 V e 20 Ah e confirmar os acessórios incluídos. Depois, compare o preço total com a importância que a bateria única e maior tem na sua rotina. A cor azul pode agradar, mas não substitui essa conferência.", "after": "A oferta citada em setembro de 2026 era de R$ 6.750 no Pix ou 12 parcelas de R$ 648, que somam R$ 7.776. **Esses valores não são preço atual garantido**; por isso, compare o custo total, e não apenas o valor mensal.\n\nO ponto de partida para decidir é verificar se a oferta atual corresponde à V9 Max 20ah com bateria removível de 48 V e 20 Ah e confirmar os acessórios incluídos. Depois, compare o preço total com a importância que a bateria única e maior tem na sua rotina. A cor azul pode agradar, mas não substitui essa conferência."}}, "faq": {}}, {"slug": "v9-max-no-uso-urbano-subidas-garupa-e-limites-do-teste", "expected_revision": 9, "old_type": "test", "new_type": "test", "old_title": "V9 Max no uso urbano: subidas, garupa e limites do teste", "new_title": "V9 Max no uso urbano: subidas, garupa e limites do teste", "blocks": {"7": {"before": "A experiência relatada inclui uso sob chuva sem problema percebido, mas isso não comprova proteção contra água em qualquer intensidade ou duração. Também foi desaconselhado deixar a bike parada e exposta à chuva por muito tempo. Para quem depende dela diariamente, ter onde guardá-la abrigada e observar a cobertura do paralama são questões práticas.\n\nNo nível mais alto, foi mencionada a possibilidade de chegar perto de 48 km/h. Isso não é uma medição de velocidade máxima garantida. Tampouco resolve a dúvida legal: a fonte comenta limites de velocidade e a classificação de veículos com acelerador, mas não fornece uma norma verificada que permita afirmar o enquadramento da V9 Max ou a dispensa de habilitação e emplacamento em determinada configuração. **Capacidade do motor e permissão para circular são questões diferentes.** Se isso determina a compra, confirme a regra aplicável e a configuração da unidade oferecida.\n\n000 foi citado para ofertas on-line em maio de 2026; não serve como preço atual. Ao comparar anúncios, confira o valor e os componentes da unidade, sobretudo se pretende levar garupa. Depois, experimente a posição de uso, observe os comandos e o paralama e avalie se a estimativa de autonomia atende à sua rotina sem tratá-la como garantia.", "after": "A experiência relatada inclui uso sob chuva sem problema percebido, mas isso não comprova proteção contra água em qualquer intensidade ou duração. Também foi desaconselhado deixar a bike parada e exposta à chuva por muito tempo. Para quem depende dela diariamente, ter onde guardá-la abrigada e observar a cobertura do paralama são questões práticas.\n\nNo nível mais alto, foi mencionada a possibilidade de chegar perto de 48 km/h. Isso não é uma medição de velocidade máxima garantida. Tampouco resolve a dúvida legal: a fonte comenta limites de velocidade e a classificação de veículos com acelerador, mas não fornece uma norma verificada que permita afirmar o enquadramento da V9 Max ou a dispensa de habilitação e emplacamento em determinada configuração. **Capacidade do motor e permissão para circular são questões diferentes.** Se isso determina a compra, confirme a regra aplicável e a configuração da unidade oferecida.\n\nUm preço abaixo de R$ 7.000 foi citado para ofertas on-line em maio de 2026; não serve como preço atual. Ao comparar anúncios, confira o valor e os componentes da unidade, sobretudo se pretende levar garupa. Depois, experimente a posição de uso, observe os comandos e o paralama e avalie se a estimativa de autonomia atende à sua rotina sem tratá-la como garantia."}}, "faq": {}}, {"slug": "v9-max-ou-ouxi-gt20-o-que-muda-na-escolha", "expected_revision": 4, "old_type": "comparison", "new_type": "comparison", "old_title": "V9 Max ou Ouxi GT20: o que muda na escolha?", "new_title": "V9 Max ou Ouxi GT20: o que muda na escolha?", "blocks": {"9": {"before": "720 para a Ouxi GT20, em agosto de 2026**. Eles registram ofertas daquele momento, não preços atuais ou garantidos. A diferença entre elas era pequena diante das variações de preço citadas para os mesmos modelos.\n\nAntes de escolher pela etiqueta, confirme o valor vigente e o que está incluído: bateria, pneus, acessórios e condições da unidade. Se as ofertas forem equivalentes, a orientação é direta: priorize a **V9 Max** se o conforto do banco para levar garupa for decisivo; considere a **Ouxi GT20** se você der mais peso à resposta do motor e quiser a indicação das setas no painel. Nenhuma dessas preferências dispensa conferir a configuração que será entregue.", "after": "A fonte citou **R$ 6.537 para a V9 Max e R$ 6.720 para a Ouxi GT20, em agosto de 2026**. Eles registram ofertas daquele momento, não preços atuais ou garantidos. A diferença entre elas era pequena diante das variações de preço citadas para os mesmos modelos.\n\nAntes de escolher pela etiqueta, confirme o valor vigente e o que está incluído: bateria, pneus, acessórios e condições da unidade. Se as ofertas forem equivalentes, a orientação é direta: priorize a **V9 Max** se o conforto do banco para levar garupa for decisivo; considere a **Ouxi GT20** se você der mais peso à resposta do motor e quiser a indicação das setas no painel. Nenhuma dessas preferências dispensa conferir a configuração que será entregue."}}, "faq": {}}, {"slug": "v9-max-ou-ufofast-vl20-o-que-realmente-muda-na-escolha", "expected_revision": 4, "old_type": "comparison", "new_type": "comparison", "old_title": "V9 Max ou UFOFAST VL20: o que realmente muda na escolha?", "new_title": "V9 Max ou UFOFAST VL20: o que realmente muda na escolha?", "blocks": {"9": {"before": "A VL20 é identificada como **UFOFAST VL20**. A V9 Max comparada é identificada pelo nome do modelo, sem uma marca comercial confirmada. Isso pode importar para quem prefere uma oferta vinculada a uma marca identificada, mas, por si só, não comprova diferença de qualidade ou facilidade de revenda.\n\n351 para a VL20 no Pix**, em uma oferta situada em setembro de 2026. A diferença à vista era pequena, e a condição mudava no parcelamento: a oferta citada para a V9 Max previa dez parcelas sem juros, enquanto a da VL20 tinha juros. Esses números são um retrato das ofertas mencionadas, não preços atuais ou permanentes. Para decidir, confira o preço total na forma de pagamento que você vai usar, o que acompanha cada unidade e as condições informadas pelo vendedor.\n\nSe as ofertas continuarem próximas, o caminho é simples: escolha a VL20 se o bagageiro dianteiro e a marca identificada forem úteis para você; considere a V9 Max se a condição de pagamento for melhor e você não precisar do bagageiro. Não há, nas configurações comparadas, uma vantagem declarada de motor ou bateria que dispense essa checagem.", "after": "A VL20 é identificada como **UFOFAST VL20**. A V9 Max comparada é identificada pelo nome do modelo, sem uma marca comercial confirmada. Isso pode importar para quem prefere uma oferta vinculada a uma marca identificada, mas, por si só, não comprova diferença de qualidade ou facilidade de revenda.\n\nA fonte citou **R$ 6.537 para a V9 Max e R$ 6.351 para a VL20 no Pix**, em uma oferta situada em setembro de 2026. A diferença à vista era pequena, e a condição mudava no parcelamento: a oferta citada para a V9 Max previa dez parcelas sem juros, enquanto a da VL20 tinha juros. Esses números são um retrato das ofertas mencionadas, não preços atuais ou permanentes. Para decidir, confira o preço total na forma de pagamento que você vai usar, o que acompanha cada unidade e as condições informadas pelo vendedor.\n\nSe as ofertas continuarem próximas, o caminho é simples: escolha a VL20 se o bagageiro dianteiro e a marca identificada forem úteis para você; considere a V9 Max se a condição de pagamento for melhor e você não precisar do bagageiro. Não há, nas configurações comparadas, uma vantagem declarada de motor ou bateria que dispense essa checagem."}}, "faq": {}}, {"slug": "v9-max-qual-versao-escolher-entre-uma-ou-duas-baterias", "expected_revision": 4, "old_type": "test", "new_type": "comparison", "old_title": "V9 Max: qual versão escolher entre uma ou duas baterias?", "new_title": "V9 Max: qual versão escolher entre uma ou duas baterias?", "blocks": {"7": {"before": "Os valores citados foram apresentados como preços de **setembro de 2026**, sujeitos a mudança.472 em dez parcelas.299 em dez parcelas. Esses números registram ofertas daquele momento; não confirmam preço nem disponibilidade atuais.\n\nNa decisão, compare primeiro a distância que você precisa percorrer com as estimativas de autonomia. Depois, confira o **valor total** de cada forma de pagamento e a configuração exata anunciada. Assim, você evita pagar por uma segunda bateria de que não precisa — ou escolher a oferta mais barata e descobrir que a capacidade não atende à sua rotina.", "after": "Os valores citados foram apresentados como preços de **setembro de 2026**, sujeitos a mudança. A V9 Max de 15,6 Ah foi citada a R$ 6.161 no Pix ou R$ 6.472 no total, em dez parcelas; a de 20 Ah, a R$ 6.750 no Pix ou 12 parcelas de R$ 648, totalizando R$ 7.776; a V9 Max S, a R$ 7.899 no Pix ou aproximadamente R$ 8.299 no total, em dez parcelas. Esses números registram ofertas daquele momento; não confirmam preço nem disponibilidade atuais.\n\nNa decisão, compare primeiro a distância que você precisa percorrer com as estimativas de autonomia. Depois, confira o **valor total** de cada forma de pagamento e a configuração exata anunciada. Assim, você evita pagar por uma segunda bateria de que não precisa — ou escolher a oferta mais barata e descobrir que a capacidade não atende à sua rotina."}}, "faq": {}}, {"slug": "v9-max-s-vale-a-compra-o-que-avaliar-antes-de-escolher-a-bike-de-duas-baterias", "expected_revision": 4, "old_type": "test", "new_type": "test", "old_title": "V9 Max S vale a compra? O que avaliar antes de escolher a bike de duas baterias", "new_title": "V9 Max S vale a compra? O que avaliar antes de escolher a bike de duas baterias", "blocks": {"6": {"before": "299,99 no cartão, em dez parcelas sem juros. **Esses eram preços de uma data específica**, não valores assegurados para uma compra posterior. A avaliação de custo-benefício muda se o preço, o parcelamento ou o conteúdo do anúncio mudarem.\n\nAntes de decidir, compare o valor atual com o que será entregue: variante V9 Max S, duas baterias de 48 V e 20 Ah, carregador e acessórios anunciados. Confira também as condições de venda e garantia informadas pelo vendedor. Para quem faz deslocamentos longos ou pretende levar garupa dentro do limite de carga, essas verificações dizem mais do que uma afirmação genérica de que a bike é a melhor compra.", "after": "A oferta citada em setembro de 2026 era de R$ 7.899 no Pix ou R$ 8.299,99 no total, em dez parcelas sem juros no cartão. **Esses eram preços de uma data específica**, não valores assegurados para uma compra posterior. A avaliação de custo-benefício muda se o preço, o parcelamento ou o conteúdo do anúncio mudarem.\n\nAntes de decidir, compare o valor atual com o que será entregue: variante V9 Max S, duas baterias de 48 V e 20 Ah, carregador e acessórios anunciados. Confira também as condições de venda e garantia informadas pelo vendedor. Para quem faz deslocamentos longos ou pretende levar garupa dentro do limite de carga, essas verificações dizem mais do que uma afirmação genérica de que a bike é a melhor compra."}}, "faq": {}}, {"slug": "vale-a-pena-fazer-entregas-com-bicicleta-eletrica-custos-autonomia-e-rotina-de-trabalho", "expected_revision": 4, "old_type": "test", "new_type": "economy", "old_title": "Vale a pena fazer entregas com bicicleta elétrica? Custos, autonomia e rotina de trabalho", "new_title": "Vale a pena fazer entregas com bicicleta elétrica? Custos, autonomia e rotina de trabalho", "blocks": {}, "faq": {}}, {"slug": "veiculo-eletrico-no-dia-a-dia-onde-pode-ajudar-e-o-que-vale-calcular", "expected_revision": 4, "old_type": "test", "new_type": "economy", "old_title": "Veículo elétrico no dia a dia: onde pode ajudar e o que vale calcular", "new_title": "Veículo elétrico no dia a dia: onde pode ajudar e o que vale calcular", "blocks": {}, "faq": {}}, {"slug": "voltz-ev1-sport-2021-usada-o-que-avaliar-antes-de-comprar", "expected_revision": 6, "old_type": "test", "new_type": "guide", "old_title": "Voltz EV1 Sport 2021 usada: o que avaliar antes de comprar", "new_title": "Voltz EV1 Sport 2021 usada: o que avaliar antes de comprar", "blocks": {}, "faq": {}}, {"slug": "voltz-evs-2021-usada-autonomia-manutencao-e-o-que-conferir-antes-de-comprar", "expected_revision": 5, "old_type": "test", "new_type": "guide", "old_title": "Voltz EVS 2021 usada: autonomia, manutenção e o que conferir antes de comprar", "new_title": "Voltz EVS 2021 usada: autonomia, manutenção e o que conferir antes de comprar", "blocks": {}, "faq": {}}, {"slug": "wanshida-gt2000-o-que-ela-entrega-e-como-avaliar-o-custo-beneficio", "expected_revision": 4, "old_type": "test", "new_type": "test", "old_title": "WANSHIDA GT2000: o que ela entrega e como avaliar o custo-benefício", "new_title": "WANSHIDA GT2000: o que ela entrega e como avaliar o custo-benefício", "blocks": {"4": {"before": "O argumento de custo-benefício da GT2000 depende do preço encontrado.700**, em setembro de 2026. Ela serve como referência daquele momento, não como preço atual ou promessa de que as mesmas condições de pagamento continuam disponíveis.\n\nComparar bicicletas apenas porque custam valores próximos também pode levar a uma escolha ruim. Uma alternativa com duas baterias pode interessar a quem prioriza distância por carga, mas exige lidar com duas unidades ao carregar. Na GT2000, o atrativo destacado é combinar uma bateria removível de 30 Ah com uma proposta de motor mais forte e uso em pisos variados. São prioridades diferentes, mesmo quando os anúncios aparecem na mesma faixa de preço.\n\nAntes de decidir, confira **o preço final e a configuração da unidade anunciada**. Depois, compare o que importa para seu trajeto: distância esperada, recarga, subidas, tipo de piso e necessidade de levar outra pessoa. A GT2000 é apresentada como bike de uso individual; quem precisa de garupa deve procurar uma opção feita para isso.", "after": "O argumento de custo-benefício da GT2000 depende do preço encontrado. A fonte citou uma oferta de aproximadamente **R$ 9.700**, em setembro de 2026. Ela serve como referência daquele momento, não como preço atual ou promessa de que as mesmas condições de pagamento continuam disponíveis.\n\nComparar bicicletas apenas porque custam valores próximos também pode levar a uma escolha ruim. Uma alternativa com duas baterias pode interessar a quem prioriza distância por carga, mas exige lidar com duas unidades ao carregar. Na GT2000, o atrativo destacado é combinar uma bateria removível de 30 Ah com uma proposta de motor mais forte e uso em pisos variados. São prioridades diferentes, mesmo quando os anúncios aparecem na mesma faixa de preço.\n\nAntes de decidir, confira **o preço final e a configuração da unidade anunciada**. Depois, compare o que importa para seu trajeto: distância esperada, recarga, subidas, tipo de piso e necessidade de levar outra pessoa. A GT2000 é apresentada como bike de uso individual; quem precisa de garupa deve procurar uma opção feita para isso."}}, "faq": {}}]$vitale_patch$)
AS p(slug text, expected_revision integer, old_type text, new_type text, old_title text, new_title text, blocks jsonb, faq jsonb);
-- Lock target rows before checking revisions, closing the concurrent-edit window.
SELECT a.id FROM public.editorial_articles a JOIN vitale_release_patch p USING (slug) FOR UPDATE OF a;
DO $$ BEGIN
 IF (SELECT count(*) FROM public.editorial_articles a JOIN vitale_release_patch p USING (slug)
 WHERE a.status='published' AND a.foundation_required IS FALSE AND a.revision=p.expected_revision AND a.content_type=p.old_type AND a.title=p.old_title
 AND NOT EXISTS (SELECT 1 FROM jsonb_each(p.blocks) b WHERE a.blocks->(b.key::integer)->>'text' IS DISTINCT FROM b.value->>'before')
 AND NOT EXISTS (SELECT 1 FROM jsonb_each(p.faq) f WHERE a.faq->(f.key::integer)->>'answer' IS DISTINCT FROM f.value->>'before')) <> 30
 THEN RAISE EXCEPTION 'Editorial data changed; abort and reconcile before release'; END IF;
END $$;
UPDATE public.editorial_articles a
SET content_type=p.new_type, title=p.new_title,
 blocks=CASE WHEN p.blocks='{}'::jsonb THEN a.blocks ELSE (
  SELECT jsonb_agg(CASE WHEN p.blocks ? ((b.n-1)::text) THEN jsonb_set(b.value, '{text}', p.blocks->((b.n-1)::text)->'after') ELSE b.value END ORDER BY b.n)
  FROM jsonb_array_elements(a.blocks) WITH ORDINALITY b(value,n)) END,
 faq=CASE WHEN p.faq='{}'::jsonb THEN a.faq ELSE (
  SELECT jsonb_agg(CASE WHEN p.faq ? ((f.n-1)::text) THEN jsonb_set(f.value, '{answer}', p.faq->((f.n-1)::text)->'after') ELSE f.value END ORDER BY f.n)
  FROM jsonb_array_elements(a.faq) WITH ORDINALITY f(value,n)) END
FROM vitale_release_patch p
WHERE a.slug=p.slug AND a.status='published' AND a.foundation_required IS FALSE AND a.revision=p.expected_revision AND a.content_type=p.old_type AND a.title=p.old_title;
DROP TABLE vitale_release_patch;
COMMIT;
